def place(slug, nav, title, desc, h1, intro, s1h, s1, s2h=None, s2=None, faq=None):
    secs = [(s1h, [s1])]
    if s2h: secs.append((s2h, [s2]))
    p = {"slug": slug, "cat": "Le bouyon par pays", "nav": nav, "title": title, "desc": desc,
         "h1": h1, "intro": intro, "sections": secs}
    if faq: p["faq"] = faq
    return p

